<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $mode==='setup'?'Create admin':'Login' ?> · ResumeIQ</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/app.css"><style>.auth{min-height:100vh;display:grid;place-items:center;padding:20px}.auth-card{width:min(410px,100%);padding:28px}.auth-logo{width:44px;height:44px;border-radius:14px;background:var(--primary);color:#fff;display:grid;place-items:center;font-weight:700}.auth h1{font-size:25px;margin:18px 0 5px}.auth p{color:var(--muted);font-size:11px}.auth label{display:block;font-size:9px;font-weight:600;margin:13px 0 5px}.auth .btn{width:100%;margin-top:17px}.error{padding:9px;border-radius:9px;background:#fff1f3;color:var(--danger);font-size:10px;margin-top:10px}</style></head><body><main class="auth"><form class="panel auth-card" method="post"><div class="auth-logo">R</div><h1><?= $mode==='setup'?'Create your admin':'Welcome back' ?></h1><p><?= $mode==='setup'?'One-time setup for this ResumeIQ workspace.':'Sign in to your recruiter workspace.' ?></p><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrfToken()?>"><?php if($mode==='setup'):?><label>Name</label><input class="control" name="name" required><?php endif?><label>Email</label><input class="control" type="email" name="email" required><label>Password</label><input class="control" type="password" name="password" minlength="8" required><button class="btn btn-primary"><?= $mode==='setup'?'Create admin':'Sign in' ?></button></form></main></body></html>
